import { test, expect } from '@playwright/test';

test.describe('Notification Preferences Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should display notification preferences section', async ({ page }) => {
    const notificationSection = page.getByRole('heading', { name: /notification preferences/i });
    await expect(notificationSection).toBeVisible();
  });

  test('should update notification preferences', async ({ page }) => {
    await page.getByLabel('Email Notifications').check();
    await page.getByLabel('SMS Notifications').uncheck();
    await page.getByRole('button', { name: /save changes/i }).click();

    const successMessage = page.getByText(/preferences updated successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
